import { randomUUID } from 'node:crypto'

/**
 * 待办分享（内存实现）。
 *
 * 一条待办可以分享给多个用户；每次分享生成一个独立记录与只读链接 token。
 * 分享是"只读一起看"：被分享者可以查看待办，但不能修改/删除。
 *
 * 这里不直接依赖 UserStore，只在展示层（presentShare）里按需读取用户资料，
 * 这样分享数据和用户表保持解耦，也避免把 passwordHash 等敏感字段带出去。
 */
export class ShareStore {
  constructor({ now = () => new Date().toISOString(), tokenFactory = () => randomUUID() } = {}) {
    this.now = now
    this.tokenFactory = tokenFactory
    this.items = new Map()
  }

  /**
   * 创建分享。同一待办重复分享给同一用户时保持幂等：
   * 不新增记录，返回已有记录并标记 created=false。
   */
  create({ todoId, ownerId, sharedWithId }) {
    const existing = this.findActive(todoId, sharedWithId)
    if (existing) return { share: existing, created: false }

    const share = {
      id: randomUUID(),
      todoId,
      ownerId,
      sharedWithId,
      token: this.tokenFactory(),
      createdAt: this.now(),
      revokedAt: null,
    }
    this.items.set(share.id, share)
    return { share, created: true }
  }

  get(id) {
    return this.items.get(id)
  }

  getByToken(token) {
    return [...this.items.values()].find((share) => share.token === token)
  }

  findActive(todoId, sharedWithId) {
    return [...this.items.values()].find(
      (share) => share.todoId === todoId && share.sharedWithId === sharedWithId && share.revokedAt == null
    )
  }

  listByTodo(todoId, { includeRevoked = false } = {}) {
    return [...this.items.values()].filter(
      (share) => share.todoId === todoId && (includeRevoked || share.revokedAt == null)
    )
  }

  listByUser(sharedWithId) {
    return [...this.items.values()].filter(
      (share) => share.sharedWithId === sharedWithId && share.revokedAt == null
    )
  }

  revoke(id) {
    const share = this.items.get(id)
    if (!share) return undefined
    if (share.revokedAt != null) return share
    const next = { ...share, revokedAt: this.now() }
    this.items.set(id, next)
    return next
  }

  /** 判断某个用户能否查看待办：owner 本人，或存在一条未撤销的分享。 */
  canView(todo, viewerId) {
    if (!todo || typeof viewerId !== 'string' || viewerId.length === 0) return false
    if (todo.ownerId === viewerId) return true
    return this.findActive(todo.id, viewerId) !== undefined
  }
}

/** 对外展示的分享结构：不包含任何用户密码信息。 */
export function presentShare(share, users) {
  const target = users?.get?.(share.sharedWithId)
  return {
    id: share.id,
    todoId: share.todoId,
    ownerId: share.ownerId,
    sharedWith: share.sharedWithId,
    sharedWithId: share.sharedWithId,
    sharedWithUser: target
      ? { id: target.id, email: target.email, displayName: target.displayName }
      : null,
    token: share.token,
    shareToken: share.token,
    url: `/shares/${share.token}`,
    createdAt: share.createdAt,
    revokedAt: share.revokedAt,
  }
}

