if (req.method === 'GET' && url.pathname === '/todos') {
  const completed = url.searchParams.has('completed')
    ? url.searchParams.get('completed') === 'true'
    : undefined
  const viewerId = url.searchParams.get('viewerId') ?? url.searchParams.get('userId')
  const sharedWith = url.searchParams.get('sharedWith') ?? url.searchParams.get('sharedWithId')

  let todos
  if (viewerId) {
    // 查看者的列表 = 自己拥有的 + 别人分享给自己的（按 id 去重）。
    const sharedIds = new Set(shares.listByUser(viewerId).map((share) => share.todoId))
    const byId = new Map()
    for (const todo of store.list({ ownerId: viewerId, completed })) byId.set(todo.id, todo)
    for (const todo of store.list({ completed })) {
      if (sharedIds.has(todo.id)) byId.set(todo.id, todo)
    }
    todos = [...byId.values()]
  } else if (sharedWith) {
    // sharedWith 只返回"分享给该用户"的待办，不混入他自己的待办。
    const sharedIds = new Set(shares.listByUser(sharedWith).map((share) => share.todoId))
    todos = store.list({ completed }).filter((todo) => sharedIds.has(todo.id))
  } else {
    todos = store.list({
      ownerId: url.searchParams.get('ownerId') ?? undefined,
      completed,
    })
  }

  const page = buildPage(todos, url.searchParams.get('page'), url.searchParams.get('pageSize'))
  return send(res, 200, page)
}

