```js
import { test, describe, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from '../src/server.js'
import { TodoStore } from '../src/store.js'
import { seedUsers } from '../src/auth/users.js'
import { ShareStore, presentShare } from '../src/sharing/shares.js'

let server
let baseUrl
let store
let users

before(async () => {
  store = new TodoStore()
  users = seedUsers()
  users.add({ id: 'user-3', email: 'carol@example.com', password: 'carol-secret', displayName: 'Carol' })
  server = createServer(store, users)
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve))
  baseUrl = `http://127.0.0.1:${server.address().port}`
})

after(async () => {
  server.closeAllConnections()
  await new Promise((resolve) => server.close(resolve))
})

async function request(path, options = {}) {
  const response = await fetch(`${baseUrl}${path}`, {
    ...options,
    headers: { 'content-type': 'application/json', ...(options.headers ?? {}) },
  })
  const text = await response.text()
  return { status: response.status, body: text ? JSON.parse(text) : null }
}

async function createTodo(title, ownerId = 'user-1') {
  const res = await request('/todos', {
    method: 'POST',
    body: JSON.stringify({ title, ownerId }),
  })
  assert.equal(res.status, 201)
  return res.body.todo
}

async function share(todoId, sharedWith, extra = {}) {
  return request(`/todos/${todoId}/share`, {
    method: 'POST',
    body: JSON.stringify({ sharedWith, ...extra }),
  })
}
```

