describe('分享待办', () => {
 test('owner 分享后返回 201、分享记录与只读链接', async () => {
  const todo = await createTodo('分享给 Bob')
  const res = await share(todo.id, 'user-2')
  assert.equal(res.status, 201)
  assert.equal(res.body.created, true)
  assert.equal(res.body.share.todoId, todo.id)
  assert.equal(res.body.share.ownerId, 'user-1')
  assert.equal(res.body.share.sharedWith, 'user-2')
  assert.equal(res.body.share.sharedWithUser.displayName, 'Bob')
  assert.equal(res.body.share.sharedWithUser.passwordHash, undefined)
  assert.match(res.body.share.url, /^\/shares\//)
  assert.equal(res.body.shareUrl, res.body.share.url)
 })

 test('重复分享同一用户是幂等的', async () => {
  const todo = await createTodo('重复分享')
  const first = await share(todo.id, 'user-2')
  const second = await share(todo.id, 'user-2')
  assert.equal(first.status, 201)
  assert.equal(second.status, 200)
  assert.equal(second.body.created, false)
  assert.equal(second.body.share.id, first.body.share.id)
  const list = await request(`/todos/${todo.id}/share`)
  assert.equal(list.body.total, 1)
 })

 test('支持按邮箱分享', async () => {
  const todo = await createTodo('按邮箱分享')
  const res = await share(todo.id, 'carol@example.com')
  assert.equal(res.status, 201)
  assert.equal(res.body.share.sharedWith, 'user-3')
 })

 test('分享对象不存在返回 404', async () => {
  const todo = await createTodo('对象不存在')
  const res = await share(todo.id, 'user-404')
  assert.equal(res.status, 404)
  assert.match(res.body.hint, /sharedWith/)
 })

