  const todo = await createTodo('缺少对象')
  const res = await request(`/todos/${todo.id}/share`, { method: 'POST', body: JSON.stringify({}) })
  assert.equal(res.status, 400)
  assert.match(res.body.hint, /sharedWith/)
 })

 test('不能分享给自己', async () => {
  const todo = await createTodo('分享给自己')
  const res = await share(todo.id, 'user-1')
  assert.equal(res.status, 400)
