function send(res, status, payload) {
  // 204 按 HTTP 规范不应带响应体，也不应声明 content-length。
  if (status === 204) {
    res.writeHead(204)
    res.end()
    return
  }
  const body = JSON.stringify(payload)
  res.writeHead(status, { ...JSON_HEADERS, 'content-length': Buffer.byteLength(body) })
  res.end(body)
}

